parameters.jsCode:
const input = $('Execute Workflow Trigger').first().json;
const aiRes = $('Generate Contextual Email Reply').first().json;
const generatedText = (aiRes.choices?.[0]?.message?.content || '').trim();

const draftSubject = input.subject.toLowerCase().startsWith('re:') 
  ? input.subject 
  : `Re: ${input.subject}`;

return [{
  json: {
    ...input,
    generatedReply: generatedText,
    draftSubject,
    requiresApproval: true,
    modelUsed: 'gpt-4o'
  }
}];
